using System;using System.IO;using System.Drawing;using System.Diagnostics;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using ThinkPadModesV3;
internal static class ModernChecks {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
 internal static int Verify(){int checks=0;Action<bool> assert=x=>{if(!x)throw new Exception("Fixture "+(checks+1)+" failed");checks++;};assert(DirectRpmSession.Verify()==0);assert(!ModernWorker.GpuNeeded(128,false));assert(ModernWorker.GpuNeeded(128,true));assert(!ModernWorker.GpuNeeded(0,false));assert(!ModernWorker.GpuNeeded(0,true));assert(ModernWorker.GuardedCadence(0,30000)==1000);assert(ModernWorker.ZeroSafe(64,true,true,true));assert(!ModernWorker.ZeroSafe(65,true,true,true));assert(!ModernWorker.ZeroSafe(55,false,true,false));assert(!ModernWorker.ZeroSafe(55,true,false,false));assert(!ModernWorker.ZeroSafe(null,true,true,false));assert(!ModernWorker.ZeroSafe(70,true,true,false));long since=-1,last=-1;NvidiaSleepGuard.Update(ref since,ref last,1000,true);NvidiaSleepGuard.Update(ref since,ref last,3000,true);assert(since==1000);assert(NvidiaSleepGuard.SecondsRemaining(-1,6000)==5);assert(NvidiaSleepGuard.SecondsRemaining(since,5999)==1);assert(NvidiaSleepGuard.SecondsRemaining(since,6000)==0);NvidiaSleepGuard.Update(ref since,ref last,4000,false);assert(since==-1);NvidiaSleepGuard.Update(ref since,ref last,5000,true);NvidiaSleepGuard.Update(ref since,ref last,9000,true);assert(since==9000);assert(ModernWorker.GpuNeeded(1,false));assert(ModernWorker.GpuNeeded(7,false));assert(!ModernWorker.ThermalSafe(0,50,null));assert(!ModernWorker.ThermalSafe(1,75,42));assert(!ModernWorker.ThermalSafe(7,50,72));assert(ModernWorker.ThermalSafe(7,70,55));assert(ModeFrame.Period(true,false)==2000);assert(ModeFrame.Period(false,false)==30000);assert(ModeFrame.Period(false,true)==500);assert(ModeFrame.Period(true,true)==500);foreach(int w in new[]{10,15,20})assert(ModernWorker.Cap(w)==w);foreach(int w in new[]{0,8,25}){bool rejected=false;try{ModernWorker.Cap(w);}catch(ArgumentException){rejected=true;}assert(rejected);}using(var c=new ModeChannel("",true,true)){var f=ModernWindow.Demo();f.Error="échantillon rejeté";f.Frames=5;f.Cadence=2000;c.Publish(f);var r=c.Read();assert(r!=null&&r.Cpu==63&&r.Fan1==0&&r.Fan2==0);assert(r.Mode==0&&r.Requested==0&&r.Target==15&&r.CapVerified);assert(r.Error==f.Error&&r.ZeroFrames==3);f.Cpu=null;f.Fan1=f.Fan2=null;f.Mode=null;f.Saver=null;c.Publish(f);r=c.Read();assert(!r.Cpu.HasValue&&!r.Fan1.HasValue&&!r.Mode.HasValue&&!r.Saver.HasValue);c.View.Write(32,13L);assert(c.Read()==null);c.View.Write(32,0L);assert(c.Read()==null);}
 using(var session=new ModernSession(true)){session.Cadence(500,true);assert(session.Channel.View.ReadInt32(8)==500);var stop=session.Stop();assert(Object.ReferenceEquals(stop,session.Stop()));stop.GetAwaiter().GetResult();session.Cadence(30000,true);session.Dispose();session.Cadence(2000,true);session.Dispose();assert(true);}
 long now=10000000;var tf=new NvmlTelemetry.TemperatureField{FieldId=308,Timestamp=now-100,ValueType=0,Return=0,Value=42.25};assert(Marshal.SizeOf(typeof(NvmlTelemetry.TemperatureField))==40);assert(NvmlTelemetry.TemperatureValid(0,tf,now));tf.Value=75;assert(NvmlTelemetry.TemperatureValid(0,tf,now));tf.Timestamp=now-4000000;assert(!NvmlTelemetry.TemperatureValid(0,tf,now));tf.Timestamp=now+1;assert(!NvmlTelemetry.TemperatureValid(0,tf,now));tf.Timestamp=now;tf.Return=3;assert(!NvmlTelemetry.TemperatureValid(0,tf,now));tf.Return=0;tf.ValueType=1;assert(!NvmlTelemetry.TemperatureValid(0,tf,now));tf.ValueType=0;tf.Value=Double.NaN;assert(!NvmlTelemetry.TemperatureValid(0,tf,now));return 0;}
 [DllImport("user32.dll")]static extern IntPtr SetThreadDpiAwarenessContext(IntPtr context);
 internal static int CloseChecks(string output){Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);Application.EnableVisualStyles();int passed=0;for(int i=0;i<20;i++){using(var f=new ModernWindow(true)){f.ShowInTaskbar=false;f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show();Application.DoEvents();var s=new ModernSession(true);f.AttachSessionForCheck(s);if(i%2==0)s.Dispose();f.DeactivateForCheck();f.Close();Application.DoEvents();f.DeactivateForCheck();f.Dispose();f.DeactivateForCheck();passed++;}}File.WriteAllText(output,new JavaScriptSerializer().Serialize(new{Passed=true,Iterations=passed,DisposedSessionCadenceSafe=true}));return 0;}
 internal static int RenderChecks(string output){SetThreadDpiAwarenessContext(new IntPtr(-1));Directory.CreateDirectory(output);var rows=new List<object>();Application.EnableVisualStyles();foreach(float scale in new[]{1f,1.5f,2f})foreach(var size in new[]{new Size(680,640),new Size(400,360)}){using(var f=new ModernWindow(true)){f.ConfigurePreview(size.Width,size.Height,scale);f.ShowInTaskbar=false;f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show();Application.DoEvents();f.PerformLayout();Application.DoEvents();using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));string file=Path.Combine(output,"ui-"+size.Width+"-"+(int)(scale*100)+".png");image.Save(file,System.Drawing.Imaging.ImageFormat.Png);}var scroll=f.Controls.OfType<Panel>().First(x=>x.Dock==DockStyle.Fill);if(scroll.HorizontalScroll.Visible)throw new Exception("Horizontal overflow");var table=scroll.Controls.OfType<TableLayoutPanel>().First();foreach(Control node in table.Controls)if(node is TableLayoutPanel&&node.Height<1)throw new Exception("Collapsed control group");File.WriteAllText(Path.Combine(output,"layout-"+size.Width+"-"+(int)(scale*100)+".json"),Json.Serialize(new{Client=scroll.ClientSize,Content=table.Bounds,RowHeights=table.GetRowHeights(),Nodes=table.Controls.Cast<Control>().Select(x=>new{Type=x.GetType().Name,Text=x.Text,Bounds=x.Bounds,Row=table.GetRow(x),Size=x.Size}).ToArray()}));rows.Add(new{Width=size.Width,Height=size.Height,ScalePercent=(int)(scale*100),HorizontalScroll=scroll.HorizontalScroll.Visible,SimulatedScaling=true});}}File.WriteAllText(Path.Combine(output,"layout-checks.json"),Json.Serialize(rows));return 0;}
 internal static async Task WaitReady(ModernSession s){long begin=CoolingPaths.Tick;while(s.Channel.View.ReadInt32(24)!=1){if(s.Reader.HasExited)throw new IOException("Échec initialisation lecteur : "+(File.Exists(Path.Combine(s.Folder,"worker-error.json"))?File.ReadAllText(Path.Combine(s.Folder,"worker-error.json")):File.Exists(Path.Combine(s.Folder,"session-result.json"))?File.ReadAllText(Path.Combine(s.Folder,"session-result.json")):"voir journal"));if(CoolingPaths.Tick-begin>30000)throw new IOException("Initialisation non confirmée");await Task.Delay(100);}}
 internal static async Task<ModeFrame> Fresh(ModernSession s,long seq=0,int limit=15000){long began=CoolingPaths.Tick;while(CoolingPaths.Tick-began<limit){var f=s.Channel.Read();if(f!=null&&f.Sequence>seq)return f;if(s.Reader.HasExited)throw new IOException("Lecteur arrêté");await Task.Delay(80);}throw new IOException("Nouvelle mesure non reçue");}
 internal static async Task QuickControls(ModernWindow window,ModernSession session,string output){var tests=new List<object>();string error=null;Guid beforeAc=WindowsPower.Read(true),beforeDc=WindowsPower.Read(false);try{await WaitReady(session);session.Cadence(500,true);foreach(int w in new[]{10,15,20}){await session.Command(2,w,w);var f=await Fresh(session);if(f.Target!=w||!f.CapVerified)throw new IOException("Plafond non confirmé: "+w);tests.Add(new{Control="CPU",Watts=w,Verified=true});}foreach(int p in new[]{1,2,3}){await session.Command(4,p,15);var f=await Fresh(session);if(f.Performance!=p)throw new IOException("Profil non confirmé: "+p);tests.Add(new{Control="Performance",Mode=p,Verified=true});}await session.Command(3,0,15);await session.Command(1,1,15);var low=await Fresh(session);if(low.Mode!=1||!low.Fan1.HasValue||!low.Fan2.HasValue)throw new IOException("Bas non confirmé");tests.Add(new{Control="Bas",Fan1=low.Fan1,Fan2=low.Fan2});await session.Command(1,7,15);long start=CoolingPaths.Tick;ModeFrame high=null;while(CoolingPaths.Tick-start<25000){high=await Fresh(session);if(high.Mode==7&&high.Fan1>=low.Fan1+500&&high.Fan2>=low.Fan2+500)break;await Task.Delay(250);}if(high==null||high.Fan1<low.Fan1+500||high.Fan2<low.Fan2+500)throw new IOException("Accélération Renforcé non mesurée");tests.Add(new{Control="Renforce",Fan1=high.Fan1,Fan2=high.Fan2});await session.Command(1,128,15);var auto=await Fresh(session);if(auto.Mode!=128)throw new IOException("Auto non confirmé");tests.Add(new{Control="Auto",Verified=true});if(auto.Cpu<=60&&auto.Gpu<=50){await session.Command(1,0,15);start=CoolingPaths.Tick;bool zero=false;while(CoolingPaths.Tick-start<35000){var f=await Fresh(session);if(f.Mode==0&&f.ZeroFrames>=3&&f.Fan1==0&&f.Fan2==0){zero=true;tests.Add(new{Control="Zero",Verified=true,Fan1=0,Fan2=0});break;}await Task.Delay(250);}if(!zero)throw new IOException("Deux RPM zéro non confirmés");}else tests.Add(new{Control="Zero",Skipped="Températures initiales non froides pour un essai automatique"});}catch(Exception e){error=e.Message;}try{await session.Command(1,128,15);await session.Command(3,0,15);WindowsPower.Set(true,beforeAc);WindowsPower.Set(false,beforeDc);}catch(Exception e){error=(error??"")+" ; restitution: "+e.Message;}File.WriteAllText(output,Json.Serialize(new{UTC=DateTime.UtcNow.ToString("o"),Passed=error==null,Error=error,Burn=false,Tests=tests}));if(!window.IsDisposed)window.Close();}
 internal static async Task HardwareSession(ModernWindow window,ModernSession session,string mode){string outdir=mode;Directory.CreateDirectory(outdir);var tests=new List<object>();Exception failure=null;try{await WaitReady(session);window.SetBenchmark("test");foreach(int w in new[]{10,15,20}){long seq=(await Fresh(session)).Sequence;string message=await session.Command(2,w,w);var f=await Fresh(session,seq);if(f.Target!=w||!f.CapVerified)throw new IOException("Plafond "+w+" W non confirmé");tests.Add(new{Stage="Cap",Watts=w,Verified=true,Cpu=f.Cpu});}await session.Command(3,0,15);foreach(int modeNumber in new[]{1,7,128}){long seq=(await Fresh(session)).Sequence;await session.Command(1,modeNumber,15);bool found=false;long begin=CoolingPaths.Tick;while(CoolingPaths.Tick-begin<15000){var f=await Fresh(session,seq);seq=f.Sequence;if(f.Mode==modeNumber&&f.Fan1.HasValue&&f.Fan2.HasValue){tests.Add(new{Stage="Fan",Mode=modeNumber,Fan1=f.Fan1,Fan2=f.Fan2});found=true;break;}}if(!found)throw new IOException("Consigne "+modeNumber+" non confirmée");}await session.Command(1,128,15);await session.Command(3,0,15);
 // No CPU/GPU burn. The owner performs load testing manually.
 var start=await Fresh(session);tests.Add(new{Stage="ZeroNotForcedByAcceptance",Cpu=start.Cpu,Gpu=start.Gpu});File.WriteAllText(Path.Combine(outdir,"hardware-checks.json"),Json.Serialize(new{UTC=DateTime.UtcNow.ToString("o"),Passed=true,Tests=tests,Burn=false}));
 foreach(string stage in new[]{"visible","background","test"}){window.SetBenchmark(stage);await Task.Delay(2500);var result=await Measure(session,stage,300);File.WriteAllText(Path.Combine(outdir,"resources-"+stage+".json"),Json.Serialize(result));}
 window.SetBenchmark("visible");await session.Command(1,128,15);await session.Command(3,0,15);File.WriteAllText(Path.Combine(outdir,"qa-complete.json"),Json.Serialize(new{UTC=DateTime.UtcNow.ToString("o"),SessionFolder=session.Folder,Completed=true}));}catch(Exception e){failure=e;}if(failure!=null){try{await session.Command(1,128,15);await session.Command(3,0,15);}catch{}File.WriteAllText(Path.Combine(outdir,"qa-error.json"),Json.Serialize(new{UTC=DateTime.UtcNow.ToString("o"),Error=failure.Message,Tests=tests}));}if(!window.IsDisposed)window.Close();}
 [StructLayout(LayoutKind.Sequential)]struct Io {public ulong ReadOps,WriteOps,OtherOps,ReadBytes,WriteBytes,OtherBytes;}
 [DllImport("kernel32.dll")]static extern bool GetProcessIoCounters(IntPtr p,out Io io);
 sealed class Sample {public string UTC;public double CpuSeconds;public long PrivateBytes;public ulong ReadBytes,WriteBytes,WriteOps;public bool IoAvailable=true;}
 static Sample Capture(int[] ids){var s=new Sample{UTC=DateTime.UtcNow.ToString("o")};foreach(int id in ids)using(var p=Process.GetProcessById(id)){p.Refresh();s.CpuSeconds+=p.TotalProcessorTime.TotalSeconds;s.PrivateBytes+=p.PrivateMemorySize64;Io io;if(GetProcessIoCounters(p.Handle,out io)){s.ReadBytes+=io.ReadBytes;s.WriteBytes+=io.WriteBytes;s.WriteOps+=io.WriteOps;}else s.IoAvailable=false;}return s;}
 static async Task<object> Measure(ModernSession session,string mode,int seconds){var ids=new[]{Process.GetCurrentProcess().Id,session.Reader.Id,session.WatcherId};var first=Capture(ids);var samples=new List<Sample>{first};long readsBefore=session.Channel.View.ReadInt64(1232);var clock=Stopwatch.StartNew();while(clock.Elapsed.TotalSeconds<seconds){await Task.Delay(Math.Min(10000,Math.Max(1,(int)((seconds-clock.Elapsed.TotalSeconds)*1000))));samples.Add(Capture(ids));}var last=samples[samples.Count-1];return new{UTC=DateTime.UtcNow.ToString("o"),Mode=mode,Seconds=clock.Elapsed.TotalSeconds,Cores=Environment.ProcessorCount,Processes=3,CpuPercent=100*(last.CpuSeconds-first.CpuSeconds)/clock.Elapsed.TotalSeconds/Environment.ProcessorCount,PrivateBytesMax=samples.Max(x=>x.PrivateBytes),ReadBytesDelta=last.ReadBytes-first.ReadBytes,WriteBytesDelta=last.WriteBytes-first.WriteBytes,WriteOperationsDelta=last.WriteOps-first.WriteOps,IoAvailable=last.IoAvailable,Acquisitions=session.Channel.View.ReadInt64(1232)-readsBefore,PeriodicJsonFiles=Directory.GetFiles(session.Folder,"rpm.json").Length,Samples=samples};}
 internal static int Victim(string output){using(var mutex=new Mutex(false,@"Global\ThinkPadModes.Calibration")){bool held=false;try{try{held=mutex.WaitOne(10000);}catch(AbandonedMutexException){held=true;}if(!held)return 75;using(var s=new ModernSession()){WaitReady(s).GetAwaiter().GetResult();s.Command(2,10,10).GetAwaiter().GetResult();File.WriteAllText(output,Json.Serialize(new{Pid=Process.GetCurrentProcess().Id,Folder=s.Folder}));Thread.Sleep(Timeout.Infinite);}}finally{if(held)mutex.ReleaseMutex();}}return 0;}
 internal static int RecoveryCheck(string output){Directory.CreateDirectory(output);string ready=Path.Combine(output,"victim-ready.json");try{using(var p=Process.Start(new ProcessStartInfo(ThinkPadManualApp.Image,"--qa-victim \""+ready+"\""){UseShellExecute=false,CreateNoWindow=true})){long start=CoolingPaths.Tick;while(!File.Exists(ready)){if(p.HasExited||CoolingPaths.Tick-start>30000)throw new IOException("Victime de test non prête");Thread.Sleep(100);}var info=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(ready));string folder=(string)info["Folder"];p.Kill();p.WaitForExit();string result=Path.Combine(folder,"recovery-result.json");start=CoolingPaths.Tick;while(!File.Exists(result)){if(CoolingPaths.Tick-start>25000)throw new IOException("Restauration après crash non confirmée");Thread.Sleep(100);}var r=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(result));if(!Convert.ToBoolean(r["AutomaticRestored"])||!Convert.ToBoolean(r["CpuLeaseRestored"]))throw new IOException("Restauration incomplète");File.WriteAllText(Path.Combine(output,"crash-check.json"),File.ReadAllText(result));}return 0;}catch(Exception e){File.WriteAllText(Path.Combine(output,"crash-check.json"),Json.Serialize(new{Error=e.Message}));return 1;}}
